import type { CardRecord, Grade, LearningPolicySettings, ProgressRecord, ReviewTiming, SavedSessionRecord, SessionOptions, SessionSummary } from "./types";
import {
  DEFAULT_DAY_START_MINUTES,
  DEFAULT_LOOKAHEAD_MINUTES,
  DEFAULT_REVIEW_INTERVALS,
  dueAtForGrade,
  progressDueAt,
} from "./scheduler";
import { coverageFirstCards, reviewFirstCards, separateSiblingCards } from "./queuePolicy";
import { DEFAULT_LEARNING_POLICY } from "./learningPolicy";

interface SessionEvent {
  card: CardRecord;
  position: number;
  insertedAt?: number;
  dueAt?: number;
  availableAfterReviewCount?: number;
  grade: Grade;
}

interface ScheduledCard {
  card: CardRecord;
  dueAt: number;
  availableAfterReviewCount?: number;
}

function shuffle<T>(values: T[]): T[] {
  const output = [...values];
  for (let index = output.length - 1; index > 0; index -= 1) {
    const target = Math.floor(Math.random() * (index + 1));
    [output[index], output[target]] = [output[target], output[index]];
  }
  return output;
}

export class StudySession {
  private queue: CardRecord[];
  private position = 0;
  private events: SessionEvent[] = [];
  private scheduled: ScheduledCard[] = [];
  private progress: Map<string, ProgressRecord>;
  private startedAt = Date.now();
  private counts: Record<Grade, number> = { again: 0, hard: 0, good: 0, easy: 0 };
  private reviewTiming: ReviewTiming;
  private learningPolicy: LearningPolicySettings;
  readonly initialCount: number;

  constructor(
    cards: CardRecord[],
    progressRecords: ProgressRecord[],
    options: SessionOptions,
    saved?: SavedSessionRecord,
    flaggedCardIds: ReadonlySet<string> = new Set(),
    reviewTiming: ReviewTiming = {
      intervals: DEFAULT_REVIEW_INTERVALS,
      dayStartMinutes: DEFAULT_DAY_START_MINUTES,
      lookaheadMinutes: DEFAULT_LOOKAHEAD_MINUTES,
    },
    learningPolicy: LearningPolicySettings = DEFAULT_LEARNING_POLICY,
  ) {
    this.reviewTiming = reviewTiming;
    this.learningPolicy = learningPolicy;
    const progress = new Map(progressRecords.map((item) => [item.cardId, item]));
    this.progress = progress;
    if (saved) {
      const cardsById = new Map(cards.map((card) => [card.id, card]));
      const restoredQueue = saved.cardIds.map((id) => cardsById.get(id));
      if (restoredQueue.every((card): card is CardRecord => Boolean(card))) {
        this.queue = restoredQueue;
        this.position = Math.min(saved.position, this.queue.length);
        this.events = saved.events.flatMap((event) => {
          const card = cardsById.get(event.cardId);
          return card ? [{ ...event, card }] : [];
        });
        if (saved.scheduled) {
          this.scheduled = saved.scheduled.flatMap((item) => {
            const card = cardsById.get(item.cardId);
            return card ? [{ card, dueAt: item.dueAt, availableAfterReviewCount: item.availableAfterReviewCount }] : [];
          });
        } else {
          // v9.1以前の「数枚後」キューを、保存済み回答時刻を使った時間制へ移行する。
          const insertedIndexes = this.events
            .flatMap((event) => event.insertedAt === undefined ? [] : [event.insertedAt])
            .sort((a, b) => b - a);
          for (const insertedAt of insertedIndexes) {
            this.queue.splice(insertedAt, 1);
            if (insertedAt < this.position) this.position = Math.max(0, this.position - 1);
          }
          const scheduledCards = new Set<string>();
          for (const event of [...this.events].reverse()) {
            event.insertedAt = undefined;
            if (scheduledCards.has(event.card.id)) continue;
            const state = progress.get(event.card.id);
            event.dueAt = state
              ? progressDueAt(state)
              : dueAtForGrade(event.grade, saved.updatedAt, this.reviewTiming.intervals, this.reviewTiming.dayStartMinutes);
            this.scheduled.push({ card: event.card, dueAt: event.dueAt });
            scheduledCards.add(event.card.id);
          }
        }
        this.counts = { ...saved.counts };
        this.initialCount = saved.initialCount;
        this.startedAt = saved.startedAt;
        this.refreshDueCards();
        return;
      }
    }

    const now = Date.now();
    let filtered = cards.filter((card) => {
      const state = progress.get(card.id);
      const isDue = state ? progressDueAt(state) <= now : true;
      if (options.filter === "flagged") return flaggedCardIds.has(card.id);
      if (options.filter === "unseen") return !state || isDue;
      if (options.filter === "missed") return isDue && (state?.lastGrade === "again" || state?.lastGrade === "hard");
      return true;
    });
    if (options.filter !== "all" && options.filter !== "flagged") {
      this.scheduled = cards.flatMap((card) => {
        const state = progress.get(card.id);
        if (!state) return [];
        const dueAt = progressDueAt(state);
        const matchesFilter = options.filter === "unseen"
          || state.lastGrade === "again"
          || state.lastGrade === "hard";
        return dueAt > now && matchesFilter ? [{ card, dueAt }] : [];
      });
    }
    if (options.order === "shuffle") filtered = shuffle(filtered);
    if ((options.sprintMinutes ?? 0) > 0 || this.learningPolicy.priorityMode === "unseen") {
      filtered = coverageFirstCards(filtered, progress);
    } else if (this.learningPolicy.priorityMode === "review") {
      filtered = reviewFirstCards(filtered, progress);
    }
    if (this.learningPolicy.siblingGuard) filtered = separateSiblingCards(filtered);
    this.queue = filtered.slice(0, options.limit > 0 ? options.limit : undefined);
    if (!this.queue.length) this.refreshDueCards(now);
    this.initialCount = this.queue.length;
  }

  get current(): CardRecord | undefined {
    return this.queue[this.position];
  }

  peek(offset = 1): CardRecord | undefined {
    return this.queue[this.position + offset];
  }

  excludeCardIds(cardIds: ReadonlySet<string>): number {
    if (!cardIds.size) return 0;
    const removedIndexes = this.queue.flatMap((card, index) => cardIds.has(card.id) ? [index] : []);
    if (!removedIndexes.length) return 0;
    const removedBeforePosition = removedIndexes.filter((index) => index < this.position).length;
    this.queue = this.queue.filter((card) => !cardIds.has(card.id));
    this.position = Math.max(0, this.position - removedBeforePosition);
    this.scheduled = this.scheduled.filter((item) => !cardIds.has(item.card.id));
    for (const event of this.events) {
      if (event.insertedAt === undefined) continue;
      if (removedIndexes.includes(event.insertedAt)) {
        event.insertedAt = undefined;
        continue;
      }
      event.insertedAt -= removedIndexes.filter((index) => index < event.insertedAt!).length;
    }
    return removedIndexes.length;
  }

  dismissCurrent(): CardRecord | undefined {
    const card = this.current;
    if (!card) return undefined;
    this.excludeCardIds(new Set([card.id]));
    return card;
  }

  get remaining(): number {
    return Math.max(0, this.queue.length - this.position);
  }

  get reviewed(): number {
    return this.events.length;
  }

  get newRemaining(): number {
    const answeredCardIds = new Set(this.events.map((event) => event.card.id));
    return new Set(this.queue.slice(this.position)
      .filter((card) => !this.progress.has(card.id) && !answeredCardIds.has(card.id))
      .map((card) => card.id)).size;
  }

  get incorrectScheduled(): number {
    const latestGrade = new Map([...this.progress].map(([cardId, state]) => [cardId, state.lastGrade]));
    for (const event of this.events) latestGrade.set(event.card.id, event.grade);
    return new Set(this.scheduled
      .filter((item) => latestGrade.get(item.card.id) === "again")
      .map((item) => item.card.id)).size;
  }

  get complete(): boolean {
    return this.position >= this.queue.length;
  }

  get nextDueAt(): number | undefined {
    return this.scheduled.reduce<number | undefined>(
      (earliest, item) => earliest === undefined || item.dueAt < earliest ? item.dueAt : earliest,
      undefined,
    );
  }

  setReviewTiming(reviewTiming: ReviewTiming): void {
    this.reviewTiming = reviewTiming;
  }

  refreshDueCards(now = Date.now()): boolean {
    const isIdle = this.position >= this.queue.length;
    const threshold = isIdle
      ? now + this.reviewTiming.lookaheadMinutes * 60 * 1000
      : now;
    const ready = this.scheduled.filter((item) => (
      item.dueAt <= threshold
      && (isIdle || item.availableAfterReviewCount === undefined || this.events.length >= item.availableAfterReviewCount)
    )).sort((a, b) => a.dueAt - b.dueAt);
    if (!ready.length) return false;
    const readyItems = new Set(ready);
    this.scheduled = this.scheduled.filter((item) => !readyItems.has(item));
    ready.forEach((item, offset) => {
      const sourceEvent = [...this.events].reverse().find((event) =>
        event.card.id === item.card.id && event.dueAt === item.dueAt && event.insertedAt === undefined,
      );
      if (sourceEvent) sourceEvent.insertedAt = this.position + offset;
    });
    this.queue.splice(this.position, 0, ...ready.map((item) => item.card));
    return true;
  }

  grade(grade: Grade, reviewedAt = Date.now()): SessionEvent | undefined {
    const card = this.current;
    if (!card) return undefined;
    const dueAt = dueAtForGrade(
      grade,
      reviewedAt,
      this.reviewTiming.intervals,
      this.reviewTiming.dayStartMinutes,
    );
    const availableAfterReviewCount = this.events.length + 1 + this.learningPolicy.minimumInterveningCards;
    const event: SessionEvent = {
      card,
      position: this.position,
      dueAt,
      availableAfterReviewCount,
      grade,
    };
    this.position += 1;
    this.scheduled.push({ card, dueAt, availableAfterReviewCount });
    this.counts[grade] += 1;
    this.events.push(event);
    this.refreshDueCards(reviewedAt);
    return event;
  }

  undo(): SessionEvent | undefined {
    const event = this.events.pop();
    if (!event) return undefined;
    if (event.insertedAt !== undefined) this.queue.splice(event.insertedAt, 1);
    if (event.dueAt !== undefined) {
      const scheduledIndex = this.scheduled.findIndex((item) => item.card.id === event.card.id && item.dueAt === event.dueAt);
      if (scheduledIndex >= 0) this.scheduled.splice(scheduledIndex, 1);
    }
    this.position = event.position;
    this.counts[event.grade] = Math.max(0, this.counts[event.grade] - 1);
    return event;
  }

  restoreUndone(event: SessionEvent): void {
    this.position = event.position + 1;
    this.counts[event.grade] += 1;
    this.events.push(event);
    if (event.insertedAt !== undefined) {
      this.queue.splice(event.insertedAt, 0, event.card);
    } else if (event.dueAt !== undefined) {
      this.scheduled.push({
        card: event.card,
        dueAt: event.dueAt,
        availableAfterReviewCount: event.availableAfterReviewCount,
      });
    }
  }

  snapshot(deckId: string, options: SessionOptions, sourceDeckId?: string): SavedSessionRecord {
    return {
      deckId,
      sourceDeckId,
      options: { ...options },
      cardIds: this.queue.map((card) => card.id),
      position: this.position,
      events: this.events.map(({ card, ...event }) => ({ ...event, cardId: card.id })),
      counts: { ...this.counts },
      initialCount: this.initialCount,
      startedAt: this.startedAt,
      updatedAt: Date.now(),
      scheduled: this.scheduled.map(({ card, dueAt, availableAfterReviewCount }) => ({
        cardId: card.id,
        dueAt,
        availableAfterReviewCount,
      })),
    };
  }

  summary(): SessionSummary {
    return {
      reviewed: this.events.length,
      ...this.counts,
      elapsedMs: Math.max(0, Date.now() - this.startedAt),
    };
  }
}
